{
  "name": "@opencode-cockpit/status",
  "version": "0.11.2",
  "description": "A statusline for OpenCode you can actually configure: declarative segments, a typed module, or your existing Claude Code statusline command",
  "type": "module",
  "license": "MIT",
  "author": "Codestz",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Codestz/opencode-cockpit.git",
    "directory": "packages/status"
  },
  "homepage": "https://cockpit.codestz.dev/status/overview/",
  "bugs": {
    "url": "https://github.com/Codestz/opencode-cockpit/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "statusline",
    "status-line",
    "tui",
    "terminal",
    "prompt"
  ],
  "exports": {
    "./server": {
      "types": "./types/server.d.ts",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./types/tui/index.d.ts",
      "default": "./dist/tui/index.js"
    },
    "./config": {
      "types": "./types/core/config/index.d.ts",
      "default": "./dist/core/config/index.js"
    },
    "./segment": {
      "types": "./types/core/authoring.d.ts",
      "default": "./dist/core/authoring.js"
    }
  },
  "engines": {
    "opencode": ">=1.18.0",
    "bun": ">=1.3.5"
  },
  "files": [
    "server.js",
    "tui.js",
    "dist",
    "types",
    "examples",
    "skills",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-cockpit/client": "0.11.2",
    "@opencode-ai/plugin": "1.18.33"
  },
  "devDependencies": {
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  },
  "bin": {
    "opencode-statusline": "./dist/cli/preview.js",
    "status": "./dist/cli/preview.js"
  }
}
